package pe.edu.upeu.casaonada.contrato.api;
import pe.edu.upeu.casaonada.contrato.domain.EstadoContrato; import pe.edu.upeu.casaonada.contrato.dto.*; import pe.edu.upeu.casaonada.contrato.service.ContratoService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.net.URI; import java.util.*;
@RestController @RequestMapping("/api/v1/contratos") public class ContratoController { private final ContratoService s; public ContratoController(ContratoService s){this.s=s;} @PostMapping public ResponseEntity<ContratoResponse> crear(@Valid @RequestBody ContratoRequest r){var x=s.crear(r);return ResponseEntity.created(URI.create("/api/v1/contratos/"+x.id())).body(x);} @GetMapping public List<ContratoResponse> listar(){return s.listar();} @GetMapping("/{id}") public ContratoResponse buscar(@PathVariable Long id){return s.buscar(id);} @PutMapping("/{id}") public ContratoResponse actualizar(@PathVariable Long id,@Valid @RequestBody ContratoRequest r){return s.actualizar(id,r);} @PatchMapping("/{id}/estado") public ContratoResponse estado(@PathVariable Long id,@RequestBody Map<String,String> b){return s.cambiarEstado(id,EstadoContrato.valueOf(b.get("estado")));} }
